using System;using System.Reflection;using System.Web.Script.Serialization;
class AiTransportCheck{static int Main(string[] args){try{var post=typeof(TV).GetMethod("PostAi",BindingFlags.NonPublic|BindingFlags.Static);string request=new JavaScriptSerializer().Serialize(new{model="openrouter/free",messages=new[]{new{role="user",content="中文传输：电视应用分析"}},response_format=TV.AiSchema()});string response=(string)post.Invoke(null,new object[]{args[0]+"/ok",request,""});var rows=TV.ParseAiRows(response);if(rows.Count!=3)throw new Exception("parser count");Console.WriteLine("PASS production .NET UTF8 HTTP transport parses recorded live Chinese response");try{post.Invoke(null,new object[]{args[0]+"/quota",request,""});throw new Exception("quota accepted");}catch(TargetInvocationException e){if(!e.InnerException.Message.Contains("自己的 API"))throw;Console.WriteLine("PASS production .NET HTTP quota error requests personal API configuration");}return 0;}catch(Exception e){Console.Error.WriteLine(e is TargetInvocationException?e.InnerException.Message:e.Message);return 1;}}}
